import { createSlice } from "@reduxjs/toolkit";
import Sign from "../pages/sign";
const initialState={firstname:'',lastname:'', email:'',
        password:'',
        conpassword:'',message:{},showmoda:false,showpass:false,showConPass:false,act:'Sign up',messagee:{}}


        const rReducer= createSlice({
            name:'register', initialState,reducers:{
                setinput:(state,action)=>{
                state[action.payload.name]=action.payload.value
                },
                setmessage: (state,action)=>{
                    state.message=action.payload

                },          setmessagee: (state,action)=>{
                    state.messagee=action.payload

                },
                showmodal:(state,action)=>{
                    state.showmoda=true;
                },  hidemodal:(state,action)=>{
                    state.showmoda=false;
                },reset: () => initialState
               
                 ,setShowConPass: (state) => {
                 state.showConPass = !state.showConPass
                 }, setact:(state)=>{
                    state.act='Sign up';
                 },setactin:(state)=>{
                    state.act='Log in';
                 },

                setshowpass: (state) => {
                state.showpass = !state.showpass;}

            },
        });

        export const{setinput,setmessage, showmodal,hidemodal,setshowpass,reset, setShowConPass,setact,setactin,setmessagee}= rReducer.actions
        export default rReducer.reducer