import React from 'react'


import '../App.css';

import Mod from '../mod';
import { IoIosEye } from "react-icons/io";
import { useDispatch, useSelector } from "react-redux";
import { setinput, setmessage, showmodal, hidemodal,setshowpass,reset,setShowConPass,setact,setactin,setmessagee} from '../redux/registslice';
import GoogleSignUp from '../components/signup';
function Sign(){
   const dispatch = useDispatch();
  const { email, password, conpassword, message, showmoda,showpass,showConPass,act,firstname,lastname,messagee } = useSelector((state) => state.register);
  
  function handlesubmit(e) {
    e.preventDefault()
    const validateerrors = {};
    if (act==='Sign up'){
        const lettersOnly = /^[A-Za-z\u0600-\u06FF\s]+$/;
    const repeatedLetters = /(.)\1{2,}/;

    if (!lettersOnly.test(firstname))
      validateerrors.firstname= "should contain just char";


    if (repeatedLetters.test(firstname)) 
      validateerrors.firstname= "dont repeat chars above tow times";
      if (!lettersOnly.test(firstname))
      validateerrors.lastname= "should contain just char";


    if (repeatedLetters.test(firstname)) 
      validateerrors.lastname= "dont repeat chars above tow times";
    
    

    if (!email.trim()) validateerrors.email = 'Email is required';
    else if (!/\S+@\S+\.\S+/.test(email)) validateerrors.email = 'Email is not valid';

    if (!password.trim()) validateerrors.password = 'Password is required';
    else if (password.length < 6) validateerrors.password = ' at least 6 characters';

    if (conpassword !== password) validateerrors.conpassword = 'Passwords do not match';

    dispatch(setmessage(validateerrors));

   
   
    if (Object.keys(validateerrors).length === 0) {
      dispatch(reset());
      dispatch(showmodal())


     
    }}else{
         

    if (!email.trim()) validateerrors.email = 'Email is required';
    else if (!/\S+@\S+\.\S+/.test(email)) validateerrors.email = 'Email is not valid';

    if (!password.trim()) validateerrors.password = 'Password is required';
       else if (password.length < 6) validateerrors.password = ' at least 6 characters';

  

    dispatch(setmessagee(validateerrors));

   
   
    if (Object.keys(validateerrors).length === 0) {
      dispatch(reset());
      dispatch(showmodal())


    }




    }
  }

  function hideModal() {
    if (showmoda) dispatch(hidemodal());
  } 
  

  return(
    <div  onClick={hideModal} className='di' >

    <form onSubmit={handlesubmit} className='for'  onClick={(e) => e.stopPropagation()} > 
       <h1>{act}</h1>
       {act==='Sign up' ?  <GoogleSignUp/>:<div></div> }
      {act==='Sign up'?  <div style={{width:'50%'}}>
        <div>
     
        <input value={firstname} className='inp' placeholder='first name'
        onChange={(e)=>{dispatch(setinput({ name: 'firstname', value: e.target.value }))} } />
      
         
          </div>
          <p >{message.firstname}</p>
          <div>
           
            <input value={lastname} className='inp' placeholder='last name'
        onChange={(e)=>{dispatch(setinput({ name: 'lastname', value: e.target.value }))} } />
                </div>
                <p >{message.lastname}</p>
                </div>
                       : <div></div>}
  
               
  <div style={{width:'50%'}}>
        <input
          className='inp'
          value={email}
          placeholder='Email'
          onChange={(e) => dispatch(setinput({ name: 'email', value: e.target.value }))} name='email'
          type='email'
        />
        <p >{act==="Sign up" ? message.email : messagee.email}</p>
        <div className='passw'>
        <input
          className='inp'
          value={password} name='password'
          placeholder='Password'
          onChange={(e) => dispatch(setinput({ name: 'password', value: e.target.value }))}
          type={showpass ? 'text' : 'password'}
        />
        
        <span
  onClick={() =>dispatch(setshowpass()) }
  className="eye"
>
<IoIosEye />
</span></div>
        <p >{act==="Sign up" ? message.password : messagee.password}</p>
{act==='Sign up' ? <div className='passw'>
        <input
          className='inp'
          value={conpassword} name='conpassword'
          placeholder='Confirm Password'
          onChange={(e) => dispatch(setinput({ name: 'conpassword', value: e.target.value }))}
          type={showConPass ? 'text' : 'password'}
        />
              <span
  onClick={() =>dispatch(setShowConPass()) }
  
   className="eye"
>
  <IoIosEye />
</span>
  <p >{message.conpassword}</p></div>    : <div></div>}
</div>

      

        
       
       
   
        
        
        
        
        
        <button  type="submit" className='regist'> {act} </button>
          <div style={{display:'flex',flexDirection:'row'}}>  <div className={act==='Sign up'? 'gray':''} style={{color:'#fff',backgroundColor:'rgba(0,0,0,0.01)',border:'1px solid #fff',padding:'1em',borderRadius:'5px',marginRight:'10px',cursor:'pointer',marginBottom:'7px'}} onClick={()=>{dispatch(setact('sign up'))}}>Sign Up</div>
          <div className={act==='Log in'? 'gray':''} style={{backgroundColor:'rgba(0,0,0,0.01)',border:'1px solid #fff',padding:'1rem',borderRadius:'5px',marginLeft:'10px',cursor:'pointer',marginBottom:'7px'}} onClick={()=>{dispatch(setactin('Login'))}}>Login</div>

            
          </div>


    </form>
   {showmodal && <Mod isVisible={showmoda} />}
    
  </div>
    )
}
export default Sign
